/bin/bash -lc "python3 - <<'PY'
import urllib.request, json, collections
snps=['rs1150779','rs6909732','rs2483211','rs7742369','rs4308051','rs8094261','rs7235010','rs2871960','rs9846396','rs224333','rs2011603','rs3791679']
base='https://www.ebi.ac.uk/gwas/rest/api'
counts=collections.Counter(); details={}; errs=[]; cache={}
def get_json(url):
    url=url.split('{',1)[0]
    if url in cache: return cache[url]
    req=urllib.request.Request(url, headers={'Accept':'application/json'})
    with urllib.request.urlopen(req, timeout=60) as r: data=json.load(r)
    cache[url]=data
    return data
for snp in snps:
    try:
        data=get_json(f'{base}/singleNucleotidePolymorphisms/{snp}/associations?size=200')
    except Exception as e:
        errs.append((snp,'assoc',e)); continue
    assocs=data.get('_embedded',{}).get('associations',[])
    print('SNP',snp,'assocs',len(assocs))
    for a in assocs:
        study_href=a.get('_links',{}).get('study',{}).get('href')
        if not study_href: continue
        try:
            st=get_json(study_href)
        except Exception as e:
            errs.append((snp,study_href,e)); continue
        pub=st.get('publicationInfo') or {}
        pmid=str(pub.get('pubmedId') or st.get('pubmedId'))
        trait=st.get('diseaseTrait')
        if isinstance(trait,dict): trait=trait.get('trait')
        title=pub.get('title') or st.get('title')
        if trait and 'height' in trait.lower():
            counts[pmid]+=1
            details.setdefault(pmid, {'title':title,'trait':trait,'examples':[]})['examples'].append((snp,a.get('pvalue'),a.get('betaNum'),a.get('betaUnit'),a.get('betaDirection')))
print('\\nHeight PMID counts')
for pmid,c in counts.most_common(30):
    d=details[pmid]
    print(pmid,c,'|',d['trait'],'|',d['title'])
    print(' ',d['examples'][:10])
print('errors',len(errs))
for e in errs[:5]: print(e[0], e[1], type(e[2]).__name__, e[2])
PY"

